<script setup lang="ts">import {onMounted,ref} from 'vue';import {useRoute,useRouter,RouterLink} from 'vue-router';import {ChevronLeft,MapPin,Package,CreditCard} from 'lucide-vue-next';import {api,idr} from '../api';import {useSession,useUi} from '../stores';const route=useRoute(),router=useRouter(),session=useSession(),ui=useUi(),order=ref<any>(null),loading=ref(true),error=ref('');async function load(){try{if(!session.user)await session.load();if(!session.user)return router.push('/login');order.value=await api(`/orders/${route.params.id}`)}catch(e:any){error.value=e.message}finally{loading.value=false}}async function payment(result:'succeed'|'fail'){try{await api(`/demo/payments/${order.value.id}/${result}`,{method:'POST'});ui.toast(result==='succeed'?'Payment completed':'Payment marked as failed');load()}catch(e:any){ui.toast(e.message,'error')}}async function cancel(){try{await api(`/orders/${order.value.id}/cancel`,{method:'POST'});ui.toast('Order canceled');load()}catch(e:any){ui.toast(e.message,'error')}}onMounted(load);</script>
<template><main class="container account-page"><RouterLink to="/account/orders" class="back-link"><ChevronLeft :size="14"/> Back to orders</RouterLink><p v-if="error" class="alert error">{{error}}</p><div v-else-if="loading" class="skeleton detail-copy-skeleton"></div><template v-else-if="order"><header class="order-detail-head"><div><small>ORDER DETAIL</small><h1>{{order.orderNumber}}</h1><p>Placed {{new Date(order.createdAt).toLocaleString('id-ID')}}</p></div><div><span class="status" :class="order.paymentStatus.toLowerCase()">{{order.paymentStatus}}</span><span class="status fulfillment">{{order.fulfillmentStatus}}</span></div></header><div class="order-detail-grid"><section class="surface"><h2><Package :size="18"/> Items</h2><article v-for="item in order.items" class="order-line"><div><b>{{item.productName}}</b><small>{{item.productSku}} · Qty {{item.quantity}}</small></div><b>{{idr(item.lineTotal)}}</b></article><div class="totals"><p><span>Subtotal</span><b>{{idr(order.subtotal)}}</b></p><p><span>Shipping</span><b>{{idr(order.shippingFee)}}</b></p><p><span>Total</span><strong>{{idr(order.totalAmount)}}</strong></p></div></section><aside><section class="surface"><h2><MapPin :size="18"/> Shipping Address</h2><p>{{order.shippingAddressSnapshot.recipientName}}<br/>{{order.shippingAddressSnapshot.addressLine}}<br/>{{order.shippingAddressSnapshot.city}}, {{order.shippingAddressSnapshot.province}} {{order.shippingAddressSnapshot.postalCode}}<br/>{{order.shippingAddressSnapshot.phone}}</p></section><section class="surface"><h2><CreditCard :size="18"/> Demo Payment</h2><p>Status: <b>{{order.paymentStatus}}</b></p><div v-if="order.paymentStatus==='PENDING'" class="button-stack"><button class="btn-primary" @click="payment('succeed')">Simulate Success</button><button class="btn-secondary" @click="payment('fail')">Simulate Failure</button><button class="danger-link" @click="cancel">Cancel Order</button></div></section></aside></div></template></main></template>
